Definition lit_word (ch : acs) (a : Z) (w : nat) (v : expr) : bool :=
  (Nat.leb w 8 && Z.leb 0 a && Z.leb (a + Z.of_nat w) (2 ^ 47) && seg_rw_ok asegs a (Z.of_nat w)
   && match kw_at ch (ELit 0) a w with Some v' => expr_eqb v' v | None => false end)%bool.

